CREATE TABLE IF NOT EXISTS `pedidos` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `ofertaId` INTEGER NOT NULL, `nombreOferta` TEXT NOT NULL, `comercio` TEXT NOT NULL, `categoria` TEXT NOT NULL, `precioPagado` REAL NOT NULL, `ahorro` REAL NOT NULL, `pesoKg` REAL NOT NULL, `horaRetiroDesde` TEXT NOT NULL, `horaRetiroHasta` TEXT NOT NULL, `estado` TEXT NOT NULL, `imagenUri` TEXT, `fecha` TEXT NOT NULL, `codigoServidor` TEXT, `fechaRetiro` TEXT NOT NULL)
CREATE TABLE IF NOT EXISTS `ofertas` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `nombre` TEXT NOT NULL, `comercio` TEXT NOT NULL, `categoria` TEXT NOT NULL, `descripcion` TEXT NOT NULL, `pesoKg` REAL NOT NULL, `precioNormal` REAL NOT NULL, `precioRescate` REAL NOT NULL, `cantidadDisponible` INTEGER NOT NULL, `horaRetiroDesde` TEXT NOT NULL, `horaRetiroHasta` TEXT NOT NULL, `imagenUri` TEXT, `propietarioId` TEXT, `estadoPublicacion` TEXT NOT NULL, `fechaRetiro` TEXT NOT NULL)
CREATE TABLE IF NOT EXISTS `notificaciones` (`id` TEXT NOT NULL, `titulo` TEXT NOT NULL, `mensaje` TEXT NOT NULL, `fechaHora` TEXT NOT NULL, `leida` INTEGER NOT NULL, `tipo` TEXT NOT NULL, `rolDestino` TEXT NOT NULL, `pedidoId` INTEGER, `ofertaId` INTEGER, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_notificaciones_rolDestino_leida` ON `notificaciones` (`rolDestino`, `leida`)
CREATE INDEX IF NOT EXISTS `index_notificaciones_fechaHora` ON `notificaciones` (`fechaHora`)
CREATE TABLE IF NOT EXISTS `sesion_activa` (`id` INTEGER NOT NULL, `usuarioId` TEXT NOT NULL, `correo` TEXT NOT NULL, `nombre` TEXT NOT NULL, `rol` TEXT NOT NULL, `nombreNegocio` TEXT, `direccion` TEXT NOT NULL, `token` TEXT NOT NULL, `refreshToken` TEXT NOT NULL, `expira` INTEGER NOT NULL, PRIMARY KEY(`id`))
